from collections import deque

class Solution:
    def countSubgraphsForEachDiameter(self, n: int, edges: List[List[int]]) -> List[int]:
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u - 1].append(v - 1)
            adj[v - 1].append(u - 1)

        def bfs(mask, src):
            dist = {src: 0}
            q = deque([src])
            while q:
                u = q.popleft()
                for w in adj[u]:
                    if (mask >> w) & 1 and w not in dist:
                        dist[w] = dist[u] + 1
                        q.append(w)
            return dist

        ans = [0] * (n - 1)
        for mask in range(3, 1 << n):
            size = bin(mask).count('1')
            if size < 2:
                continue
            dist = bfs(mask, (mask & -mask).bit_length() - 1)
            if len(dist) != size:
                continue
            far = max(dist, key=dist.get)
            ans[max(bfs(mask, far).values()) - 1] += 1
        return ans

