class Solution {
    private List<List<Integer>> adj;

    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0] - 1).add(e[1] - 1);
            adj.get(e[1] - 1).add(e[0] - 1);
        }
        int[] ans = new int[n - 1];
        for (int mask = 3; mask < (1 << n); mask++) {
            int size = Integer.bitCount(mask);
            if (size < 2) continue;
            int[] d1 = bfs(mask, Integer.numberOfTrailingZeros(mask), n);
            int reached = 0, far = 0, best = -1;
            for (int i = 0; i < n; i++)
                if (d1[i] >= 0) {
                    reached++;
                    if (d1[i] > best) { best = d1[i]; far = i; }
                }
            if (reached != size) continue;
            int[] d2 = bfs(mask, far, n);
            int dia = 0;
            for (int d : d2) dia = Math.max(dia, d);
            ans[dia - 1]++;
        }
        return ans;
    }

    private int[] bfs(int mask, int src, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[src] = 0;
        Queue<Integer> q = new ArrayDeque<>();
        q.add(src);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int w : adj.get(u))
                if (((mask >> w) & 1) == 1 && dist[w] < 0) {
                    dist[w] = dist[u] + 1;
                    q.add(w);
                }
        }
        return dist;
    }
}

