class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        final int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[n][n];
        for (int[] row : dist) Arrays.fill(row, INF);
        for (int i = 0; i < n; i++) dist[i][i] = 0;
        for (int[] e : edges) { dist[e[0] - 1][e[1] - 1] = 1; dist[e[1] - 1][e[0] - 1] = 1; }
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);

        int[] ans = new int[n - 1];
        for (int mask = 3; mask < (1 << n); mask++) {
            int size = Integer.bitCount(mask), cnt = 0;
            for (int[] e : edges)
                if (((mask >> (e[0] - 1)) & 1) == 1 && ((mask >> (e[1] - 1)) & 1) == 1) cnt++;
            if (size < 2 || cnt != size - 1) continue;
            int d = 0;
            for (int i = 0; i < n; i++)
                if (((mask >> i) & 1) == 1)
                    for (int j = i + 1; j < n; j++)
                        if (((mask >> j) & 1) == 1) d = Math.max(d, dist[i][j]);
            ans[d - 1]++;
        }
        return ans;
    }
};

